var view=new PixelRect(0,0,20,20);var raw=Enumerable.Range(0,1600).Select(n=>(byte)(n%256)).ToArray();var baseline=(byte[])raw.Clone();
foreach(var kind in Enum.GetValues<PixelSelectionKind>()){
 var region=new PixelSelection{Kind=kind,Bounds=new(4,4,8,8),Points=[new(4,4),new(12,4),new(8,12)]};region.Validate(view);var fill=PixelStudio.Edit(raw,20,20,region,[20,30,40,255]);
 bool inside=true,outside=true;for(int y=0;y<20;y++)for(int x=0;x<20;x++){var i=(y*20+x)*4;if(region.Contains(x+.5,y+.5))inside&=fill.AsSpan(i,4).SequenceEqual(new byte[]{20,30,40,255});else outside&=fill.AsSpan(i,4).SequenceEqual(raw.AsSpan(i,4));}
 Check(inside,"Fill exactly selected pixel centers: "+kind);Check(outside,"Preserve all outside pixels: "+kind);Check(raw.SequenceEqual(baseline),"Never mutate original input: "+kind);
 var extracted=PixelStudio.Extract(raw,20,20,region);Check(extracted.Length==8*8*4,"Extract keeps source pixel dimensions: "+kind);
 var erased=PixelStudio.Edit(raw,20,20,region,null);Check(erased[(6*20+7)*4+3]==0,"Erase selected pixel to transparent: "+kind);
 var copy=region.Copy();copy.Translate(200,-200,view);Check(copy.Bounds.X==12&&copy.Bounds.Y==0&&region.Bounds==new PixelRect(4,4,8,8),"Move clamps independently: "+kind);
}
var polygon=new PixelSelection{Kind=PixelSelectionKind.Lasso,Bounds=new(0,0,20,20),Points=Enumerable.Range(0,96).Select(i=>new AnnotationPoint(10+9*Math.Cos(i*Math.PI/48),10+9*Math.Sin(i*Math.PI/48))).ToList()};var masked=PixelStudio.Edit(raw,20,20,polygon,[77,88,99,255]);bool same=true;for(int y=0;y<20;y++)for(int x=0;x<20;x++){var expected=polygon.Contains(x+.5,y+.5)?new byte[]{77,88,99,255}:raw.AsSpan((y*20+x)*4,4).ToArray();same&=masked.AsSpan((y*20+x)*4,4).SequenceEqual(expected);}Check(same,"Scanline lasso matches geometric mask at every pixel");
var ellipse=new PixelSelection{Kind=PixelSelectionKind.Ellipse,Bounds=new(0,0,10,10)};Check(!ellipse.Contains(.5,.5)&&ellipse.Contains(5,5),"Ellipse keeps bounding corners outside mask");
var lasso=new PixelSelection{Kind=PixelSelectionKind.Lasso,Bounds=new(0,0,10,10),Points=[new(0,0),new(10,0),new(0,10)]};Check(lasso.Contains(1,1)&&!lasso.Contains(9,9),"Lasso polygon inclusion follows its outline");
