var doc=new EditorDocument{OriginalWidth=20,OriginalHeight=20,Annotations=[new(){Kind=AnnotationKind.ImageLayer,X1=2,Y1=3,X2=3,Y2=4,PixelPng=png}]};doc.Validate(20,20,"");Check(doc.Version==11&&doc.Clone().Annotations[0].PixelPng==png,"Schema11 stores pasted layer losslessly");
var session=new EditorSession(doc);var layer=doc.Annotations[0];session.Change(d=>d.Annotations[0].Translate(4,5));session.Undo();Check(session.Document.Annotations[0].X1==2&&session.Document.Annotations[0].PixelPng==png,"Undo raster movement preserves image bytes");session.Redo();Check(session.Document.Annotations[0].X1==6,"Redo raster movement");
