var packet=AnnotationClipboard.Copy(doc,[layer.Id]);var target=new EditorDocument{OriginalWidth=100,OriginalHeight=100};AnnotationClipboard.Paste(target,packet,16,a=>new(a.Left,a.Top,a.Width,a.Height));Check(target.Annotations[0].PixelPng==png&&target.Annotations[0].Id!=layer.Id,"Object clipboard retains raster and remaps identity");
